'use strict';
const BASE=document.body.dataset.base||'./';
const {categories,prepare,filterProducts,sanitizeCart,subtotal}=VitaCore;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const src=s=>/^https:\/\//.test(s)?s:BASE+s;
const paths={search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',truck:'<path d="M2 5h12v12H2V5Zm12 5h4l4 4v3h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',message:'<path d="M4 4h16v13H9l-5 4V4Z"/><path d="M8 9h8m-8 4h5"/>',leaf:'<path d="M5 20c9 1 16-5 15-16C9 3 3 10 5 20Zm0 0L16 9"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',gem:'<path d="m3 9 5-6h8l5 6-9 13L3 9Zm0 0h18M8 3l-1 6 5 13 5-13-1-6"/>',drop:'<path d="M12 2C10 6 4 11 4 15a8 8 0 0 0 16 0c0-4-6-9-8-13Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',circles:'<circle cx="8" cy="8" r="4"/><circle cx="16" cy="15" r="5"/><circle cx="6" cy="18" r="2"/><path d="m18 4 2 2"/>',mushroom:'<path d="M3 13a9 9 0 0 1 18 0H3Zm6 0v8h6v-8"/><path d="M7 9h.01M16 8h.01M12 6h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.grid}</svg>`;
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
let products=[],cart={},page=1,detailQuantity=1,toastTimeout;
let filters={query:'',category:'',brand:'',ingredient:'',available:false,sale:false,maxPrice:'',sort:'original'};
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),2600);}
function saveCart(){try{localStorage.setItem('vitashop-cart-v1',JSON.stringify(cart));}catch{}renderCart();}
function add(id,quantity=1){const p=products.find(p=>p.id===id);if(!p?.available)return;cart[id]=Math.min(99,(cart[id]||0)+quantity);saveCart();toast('Producto agregado al carrito');}
function changeQty(id,delta){if(!cart[id])return;cart[id]=Math.max(1,Math.min(99,cart[id]+delta));saveCart();}
function productCard(p){return `<article class="product-card"><a href="#producto/${esc(p.slug)}" class="product-image" aria-label="Ver ${esc(p.name)}">${!p.available?'<span class="product-badge out">Sin stock</span>':p.oldPrice?`<span class="product-badge">${Math.round(100*(1-p.price/p.oldPrice))}% de descuento</span>`:''}<img src="${esc(src(p.image))}" alt="${esc(p.name)}" loading="lazy" width="230" height="220"></a><div class="product-info"><span class="brand-label">${esc(p.brand)}</span><h3><a href="#producto/${esc(p.slug)}">${esc(p.name.split('|')[0].trim())}</a></h3><p class="product-presentation">${esc(p.presentation||p.name.split('|').slice(1,-1).join(' · '))}</p><div class="product-price"><strong>${money(p.price)}</strong>${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</div><div class="card-bottom"><span class="availability ${p.available?'':'out'}">${p.available?'Disponible':'Sin stock'}</span><button class="add-button" data-add="${p.id}" ${p.available?'':'disabled'} aria-label="Agregar ${esc(p.name)}">${icon('plus')} Agregar</button></div></div></article>`;}
function options(id,values){const node=$(id);const initial=node.options[0].outerHTML;node.innerHTML=initial+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
function renderHome(){const hero=products.slice(0,3);$('hero-products').innerHTML=hero.map(p=>`<a class="hero-bottle" href="#producto/${p.slug}" aria-label="Ver ${esc(p.name)}"><img src="${esc(src(p.image))}" alt="${esc(p.name)}" width="190" height="260"></a>`).join('');$('featured').innerHTML=products.slice(0,8).map(productCard).join('');$('category-grid').innerHTML=categories.slice(0,6).map(c=>`<button class="category-card" data-category="${esc(c.name)}"><span>${icon(c.icon)}</span><strong>${esc(c.name)}</strong><small>${products.filter(p=>p.category===c.name).length} productos</small></button>`).join('');const topBrands=[...new Set(products.map(p=>p.brand))].filter(b=>b!=='Otras marcas').sort((a,b)=>products.filter(p=>p.brand===b).length-products.filter(p=>p.brand===a).length).slice(0,6);$('brand-list').innerHTML=topBrands.map(b=>`<button data-brand="${esc(b)}">${esc(b)}</button>`).join('');$('catalogue-total').textContent=`${products.length} productos`;options('category-filter',categories.map(c=>c.name));options('brand-filter',[...new Set(products.map(p=>p.brand))].sort((a,b)=>a.localeCompare(b,'es')));options('ingredient-filter',[...new Set(products.map(p=>p.ingredient))].sort((a,b)=>a.localeCompare(b,'es')));}
function renderCatalog(){const filtered=filterProducts(products,filters);const pages=Math.max(1,Math.ceil(filtered.length/24));page=Math.min(page,pages);$('result-count').textContent=filtered.length?`${filtered.length} productos · ${((page-1)*24)+1}–${Math.min(page*24,filtered.length)}`:'Sin resultados';$('product-grid').innerHTML=filtered.length?filtered.slice((page-1)*24,page*24).map(productCard).join(''):'<div class="empty-state"><h3>No encontramos esos productos.</h3><p>Probá con otra palabra o quitá algún filtro.</p><button class="button" data-clear>Limpiar búsqueda y filtros</button></div>';let visiblePages=[...new Set([1,page-1,page,page+1,pages])].filter(n=>n>0&&n<=pages).sort((a,b)=>a-b);$('pagination').innerHTML=pages>1?`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="Página anterior">←</button>${visiblePages.map((n,i)=>`${i>0&&n-visiblePages[i-1]>1?'<span>…</span>':''}<button data-page="${n}" class="${n===page?'active':''}" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')}<button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Página siguiente">→</button>`:'';const active=[['query',filters.query],['category',filters.category],['brand',filters.brand],['ingredient',filters.ingredient],['maxPrice',filters.maxPrice?`Hasta ${money(Number(filters.maxPrice))}`:''],['available',filters.available?'Disponibles':''],['sale',filters.sale?'Con descuento':'']].filter(([,v])=>v);$('active-filters').innerHTML=active.map(([k,v])=>`<button class="filter-chip" data-remove-filter="${k}" aria-label="Quitar filtro ${esc(v)}">${esc(v)} ×</button>`).join('');}
function syncFilters(){for(const [id,key] of [['category-filter','category'],['brand-filter','brand'],['ingredient-filter','ingredient'],['max-price','maxPrice'],['sort','sort']])$(id).value=filters[key];$('search').value=filters.query;$('available-filter').checked=filters.available;$('sale-filter').checked=filters.sale;}
function clearFilters(){filters={query:'',category:'',brand:'',ingredient:'',available:false,sale:false,maxPrice:'',sort:'original'};page=1;syncFilters();renderCatalog();}
function goCatalog(){if(location.hash!=='#catalogo')location.hash='catalogo';else $('catalogo').scrollIntoView({behavior:'smooth'});}
function renderCart(){const quantity=Object.values(cart).reduce((a,b)=>a+b,0);$('cart-count').textContent=quantity;$('drawer-count').textContent=`(${quantity})`;$('cart-trigger').setAttribute('aria-label',`Abrir carrito, ${quantity} productos`);const entries=Object.entries(cart).map(([id,q])=>({p:products.find(p=>p.id===id),q})).filter(x=>x.p);$('cart-items').innerHTML=entries.length?entries.map(({p,q})=>`<article class="cart-item"><img src="${esc(src(p.image))}" alt="${esc(p.name)}" width="70" height="90"><div><span class="brand-label">${esc(p.brand)}</span><h3><a href="#producto/${p.slug}" data-close="cart-dialog">${esc(p.name)}</a></h3><div class="item-meta"><strong>${money(p.price*q)}</strong><small>${money(p.price)} c/u</small></div><div class="cart-item-controls"><div class="quantity"><button data-cart-qty="${p.id}" data-delta="-1" aria-label="Restar uno" ${q===1?'disabled':''}>−</button><span>${q}</span><button data-cart-qty="${p.id}" data-delta="1" aria-label="Sumar uno" ${q===99?'disabled':''}>+</button></div><button class="remove" data-remove="${p.id}" aria-label="Quitar ${esc(p.name)}">Quitar</button></div></div></article>`).join(''):'<div class="empty-state"><h3>Tu carrito está vacío.</h3><p>Elegí un producto para comenzar.</p><button class="button" data-close="cart-dialog" data-explore>Explorar catálogo</button></div>';$('cart-bottom').innerHTML=entries.length?`<div class="totals-row"><span>Productos (${quantity})</span><span>${money(subtotal(cart,products))}</span></div><div class="totals-row"><span>Envío</span><span>A cotizar</span></div><div class="totals-row total"><strong>Subtotal</strong><strong>${money(subtotal(cart,products))}</strong></div><button class="button" id="checkout-button">Revisar compra ${icon('arrow')}</button><p class="demo-note">Vista de revisión. No se generan pedidos ni se procesan pagos.<br>Stock y precios corresponden al catálogo recuperado.</p>`:'';}
function checkout(){if(!Object.keys(cart).length)return;$('cart-dialog').close();$('checkout-content').innerHTML=`<p>Este resumen permite probar el recorrido de compra. No ingreses datos personales ni realices pagos.</p><div class="checkout-box"><h3>Tu selección</h3>${Object.entries(cart).map(([id,q])=>{const p=products.find(p=>p.id===id);return `<div class="totals-row"><span>${q} × ${esc(p.name.split('|')[0].trim())}</span><strong>${money(p.price*q)}</strong></div>`;}).join('')}<div class="totals-row total"><strong>Subtotal</strong><strong>${money(subtotal(cart,products))}</strong></div><div class="totals-row"><span>Envío</span><span>Pendiente de cotización</span></div></div><div class="checkout-box"><h3>1. Medio de pago previsto</h3><div class="payment-options"><label><input type="radio" name="payment" value="mercadopago" checked> Mercado Pago</label><label><input type="radio" name="payment" value="transferencia"> Transferencia</label></div><p id="payment-note">Mercado Pago estará disponible cuando el comercio conecte su cuenta. No se abrirá ningún pago en esta vista.</p></div><div class="checkout-box"><h3>2. Entrega</h3><form id="shipping-form" class="shipping-form"><input name="zipcode" aria-label="Código postal" placeholder="Código postal" pattern="(?:[0-9]{4}|[A-Za-z][0-9]{4}[A-Za-z]{3})" required maxlength="8"><button type="submit" class="button">Consultar envío</button></form><div class="shipping-result" id="shipping-result" role="status">La cotización se habilitará con el servicio de envío elegido por el comercio.</div></div><div class="checkout-disabled"><strong>Compra todavía no habilitada</strong><br>Falta conectar los pagos, confirmar el stock y configurar los envíos. Esta prueba no reserva productos.</div>`;$('checkout-dialog').showModal();icons();}
function renderDetail(p){detailQuantity=1;const gallery=(p.localGallery||[p.image]).filter(Boolean);const related=products.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,4);$('product-view').innerHTML=`<nav class="breadcrumbs" aria-label="Ruta del producto"><a href="#inicio">Inicio</a><span>/</span><a href="#catalogo">Productos</a><span>/</span><span>${esc(p.ingredient)}</span></nav><div class="detail-layout"><div><img id="detail-image" class="detail-main-image" src="${esc(src(gallery[0]))}" alt="${esc(p.name)}" width="500" height="480"><div class="detail-thumbs">${gallery.map((s,i)=>`<button class="${i===0?'active':''}" data-thumb="${esc(s)}" aria-label="Ver foto ${i+1}"><img src="${esc(src(s))}" alt="${esc(p.name)} · foto ${i+1}" width="55" height="65" loading="lazy"></button>`).join('')}</div></div><div class="detail-info"><span class="brand-label">${esc(p.brand)}</span><h1>${esc(p.name)}</h1><span class="detail-chip">${esc(p.category)}</span><div class="product-price"><strong>${money(p.price)}</strong>${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</div><span class="availability ${p.available?'':'out'}">${p.available?'Disponible en el catálogo recuperado':'Sin stock en el catálogo recuperado'}</span><div class="detail-actions"><div class="quantity"><button data-detail-qty="-1" aria-label="Reducir cantidad">−</button><span id="detail-qty">1</span><button data-detail-qty="1" aria-label="Aumentar cantidad">+</button></div><button class="button" data-detail-add="${p.id}" ${p.available?'':'disabled'}>${icon('bag')} ${p.available?'Agregar al carrito':'Sin stock'}</button></div><p class="detail-stock">Precio y disponibilidad recuperados el 12/10/2026. Compra deshabilitada en esta vista.</p>${p.variants?.length?`<div class="product-note">Presentaciones publicadas: ${p.variants.map(v=>`${esc(v.name)}: ${v.options.map(o=>esc(o.name)).join(', ')}`).join(' · ')}. La disponibilidad por variante debe confirmarse con la exportación del comercio.</div>`:''}<h2 class="detail-description-title">Información del producto</h2><div class="detail-description">${esc(p.description||p.name)}</div><div class="product-consult">¿Querés consultar por esta presentación? <a href="https://wa.me/541170649976?text=${encodeURIComponent('Hola, quisiera información sobre '+p.name)}" target="_blank" rel="noopener">Hablar con VitaShop ↗</a></div><div class="product-note">La información corresponde a la ficha publicada por el comercio. Los suplementos no reemplazan una alimentación variada. Consultá a un profesional de salud para evaluar su uso.</div></div></div><h2 class="related-title">Más productos de esta categoría.</h2><div class="products featured">${related.map(productCard).join('')}</div>`;document.title=p.name+' · VitaShop';}
function route(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('producto/')){const p=products.find(p=>p.slug===hash.slice(9));$('home').hidden=true;$('catalogo').hidden=true;$('product-view').hidden=false;if(p)renderDetail(p);else $('product-view').innerHTML='<div class="empty-state"><h1>Producto no encontrado</h1><p>Volvé al catálogo para explorar los productos disponibles.</p><a class="button" href="#catalogo">Ver catálogo</a></div>';window.scrollTo({top:0,behavior:'instant'});}else{$('home').hidden=false;$('catalogo').hidden=false;$('product-view').hidden=true;document.title='VitaShop · Suplementos y vitaminas';if(hash&&$(hash))requestAnimationFrame(()=>$(hash).scrollIntoView({behavior:'smooth'}));}}
const information={envios:['Envíos','Vitashop publica entregas a todo el país. En esta nueva versión todavía falta conectar el servicio de envíos y acordar las tarifas con el comercio. El costo de envío no está incluido en el subtotal del carrito. No hay una tarifa inventada ni una promesa de entrega activa en esta vista.'],pagos:['Medios de pago','Se prevé incorporar Mercado Pago y transferencia bancaria. Para activarlos, el comercio debe conectar su cuenta de cobro y confirmar sus datos bancarios. En esta vista no se solicitan datos de tarjeta, no se procesan pagos y no se generan pedidos.'],devoluciones:['Cambios y devoluciones','Las condiciones de cambios y devoluciones de la tienda independiente deben ser confirmadas por el comercio antes de habilitar las ventas. Consultá con Vitashop para conocer las condiciones vigentes de una compra realizada en su tienda actual.'],privacidad:['Privacidad de esta vista','El carrito se conserva en este navegador usando almacenamiento local. Esta vista no envía pedidos ni registra datos personales del comprador. Los enlaces de contacto abren WhatsApp o tu aplicación de correo. La política de privacidad de la tienda definitiva se incorporará antes de activar las ventas.']};
document.addEventListener('click',e=>{const node=e.target.closest('button,a');if(!node)return;if(node.dataset.close){$(node.dataset.close).close();}if(node.dataset.add)add(node.dataset.add);if(node.dataset.detailAdd)add(node.dataset.detailAdd,detailQuantity);if(node.dataset.remove){delete cart[node.dataset.remove];saveCart();}if(node.dataset.cartQty)changeQty(node.dataset.cartQty,Number(node.dataset.delta));if(node.dataset.detailQty){detailQuantity=Math.max(1,Math.min(99,detailQuantity+Number(node.dataset.detailQty)));$('detail-qty').textContent=detailQuantity;}if(node.dataset.thumb){$('detail-image').src=src(node.dataset.thumb);document.querySelectorAll('[data-thumb]').forEach(b=>b.classList.toggle('active',b===node));}if(node.dataset.category){clearFilters();filters.category=node.dataset.category;syncFilters();renderCatalog();goCatalog();}if(node.dataset.brand){clearFilters();filters.brand=node.dataset.brand;syncFilters();renderCatalog();goCatalog();}if(node.dataset.page){page=Number(node.dataset.page);renderCatalog();$('catalogo').scrollIntoView({behavior:'smooth'});}if(node.hasAttribute('data-clear')||node.id==='clear-filters')clearFilters();if(node.dataset.removeFilter){filters[node.dataset.removeFilter]=['available','sale'].includes(node.dataset.removeFilter)?false:'';page=1;syncFilters();renderCatalog();}if(node.hasAttribute('data-explore'))goCatalog();if(node.id==='checkout-button')checkout();if(node.dataset.info){const [title,text]=information[node.dataset.info];$('info-title').textContent=title;$('info-content').innerHTML=`<p>${esc(text)}</p>`;$('info-dialog').showModal();}});
$('cart-trigger').addEventListener('click',()=>{$('cart-dialog').showModal();});
$('search-form').addEventListener('submit',e=>{e.preventDefault();filters.query=$('search').value.trim();page=1;renderCatalog();goCatalog();});
for(const [id,key] of [['category-filter','category'],['brand-filter','brand'],['ingredient-filter','ingredient'],['max-price','maxPrice'],['sort','sort']])$(id).addEventListener('change',()=>{filters[key]=$(id).value;page=1;renderCatalog();});
for(const [id,key] of [['available-filter','available'],['sale-filter','sale']])$(id).addEventListener('change',()=>{filters[key]=$(id).checked;page=1;renderCatalog();});
document.addEventListener('submit',e=>{if(e.target.id==='shipping-form'){e.preventDefault();$('shipping-result').textContent='Código postal válido. La tarifa real estará disponible cuando se conecte el servicio de envíos. En esta vista no se calcula un costo ni se genera una entrega.';}});
document.addEventListener('change',e=>{if(e.target.name==='payment')$('payment-note').textContent=e.target.value==='transferencia'?'La transferencia se habilitará al confirmar el alias o CBU del comercio. No hay datos bancarios configurados en esta vista.':'Mercado Pago estará disponible cuando el comercio conecte su cuenta. No se abrirá ningún pago en esta vista.';});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
window.addEventListener('hashchange',()=>{if(products.length)route();});
icons();
async function boot(){try{const response=await fetch(BASE+'assets/catalogue.json');if(!response.ok)throw new Error('No se pudo cargar el catálogo');const raw=await response.json();products=raw.products.map(prepare);let saved={};try{saved=JSON.parse(localStorage.getItem('vitashop-cart-v1')||'{}');}catch{}cart=sanitizeCart(saved,products);renderHome();renderCatalog();renderCart();if(!location.hash&&document.body.dataset.product)location.hash='producto/'+document.body.dataset.product;else route();}catch(error){$('featured').innerHTML='<div class="empty-state"><h3>No pudimos cargar el catálogo.</h3><p>Actualizá la página para volver a intentar.</p></div>';$('product-grid').innerHTML=$('featured').innerHTML;console.error(error);}}
boot();
